import{At as e,lt as t,st as n,z as r}from"./chunks/framework.Cb3dc2_V.js";var i=JSON.parse(`{"title":"垂直剖面","description":"","frontmatter":{"author":"wangrl"},"headers":[],"relativePath":"doc-draw/m4-w-fast/vertical-section/index.md","filePath":"doc-draw/m4-w-fast/vertical-section/index.md","lastUpdated":1785826081000}`),a={name:`doc-draw/m4-w-fast/vertical-section/index.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="垂直剖面" tabindex="-1">垂直剖面 <a class="header-anchor" href="#垂直剖面" aria-label="Permalink to “垂直剖面”">​</a></h1><blockquote><p>本节由codex施工</p></blockquote><p>垂直剖面模块把三维规则体数据统一为 <code>IVolumeSource</code>，再按路线生成二维剖面、三维墙体纹理或体积场景中的路线面。数据解析、水平层适配、路线采样和统计均由 <code>m4-w-fast</code> 完成，显示端只消费公共结果。</p><h2 id="数据链" tabindex="-1">数据链 <a class="header-anchor" href="#数据链" aria-label="Permalink to “数据链”">​</a></h2><ol><li><code>loadVolumeSource</code> 按明确格式解析 ZIP，产出带分块读取能力的 <code>IVolumeSource</code>。</li><li><code>createHorizontalRasterGrid</code> 读取指定时间和高度，生成北向第一行、西向第一列的 <code>RasterGrid</code>。</li><li><code>createVolumeSection</code> 沿路线按格点或双线性插值采样，生成二维剖面。</li><li>二维结果可转为 <code>RasterGrid</code> 或路线面；原始 <code>IVolumeSource</code> 可直接交给独立 WebGPU 场景或 Mars3D 的 Cesium 原生体积图层。</li></ol><h2 id="入口" tabindex="-1">入口 <a class="header-anchor" href="#入口" aria-label="Permalink to “入口”">​</a></h2><table tabindex="0"><thead><tr><th>子路径</th><th>主要能力</th><th>UMD 全局变量</th></tr></thead><tbody><tr><td><code>m4-w-fast/volume-data</code></td><td>ZIP 解析、<code>IVolumeSource</code> 创建</td><td><code>M4WVolumeData</code></td></tr><tr><td><code>m4-w-fast/volume-section</code></td><td>水平层、路线剖面、统计与结果适配</td><td><code>M4WVolumeSection</code></td></tr><tr><td><code>m4-w-fast/volume-scene</code></td><td>独立 WebGPU 体积、切片和路线面</td><td><code>M4WVolumeScene</code></td></tr><tr><td><code>m4-w-fast/volume-mars3d-native</code></td><td>Cesium 原生体积与轴切片</td><td><code>M4WVolumeMars3dNative</code></td></tr></tbody></table><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to “当前状态”">​</a></h2><table tabindex="0"><thead><tr><th>图标</th><th>含义</th></tr></thead><tbody><tr><td>✅</td><td>已实现并有独立文档</td></tr></tbody></table><table tabindex="0"><thead><tr><th>状态</th><th>能力</th></tr></thead><tbody><tr><td>✅</td><td>雷达规则体 ZIP 解析与分块数据源</td></tr><tr><td>✅</td><td>水平层、二维路线剖面与三维剖面墙</td></tr><tr><td>✅</td><td>独立 WebGPU 体积、路线面和轴切片</td></tr><tr><td>✅</td><td>Mars3D Cesium 原生三维体积与轴切片</td></tr></tbody></table>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};